#include <stdio.h>
#include <stdlib.h>

int comparar(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int n;
    scanf("%d", &n);

    int a[1500];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    qsort(a, n, sizeof(int), comparar);

    long long total = 0;

    for (int i = 0; i < n - 2; i++) {
        int j = i + 1;
        int k = n - 1;

        while (j < k) {
            if ((long long)a[i] + a[j] > a[k]) {
                total += k - j;
                k--;
            } else {
                j++;
            }
        }
    }

    printf("%lld\n", total);
    return 0;
}
